{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "intro_text",
        "divider_1",
        "section_h2_remedies",
        "subsection_h3_otc",
        "otc_saline_stack",
        "otc_honey_stack",
        "otc_pain_relievers_stack",
        "subsection_h3_non_medical",
        "non_medical_hydration_stack",
        "non_medical_rest_stack",
        "non_medical_humidifier_stack",
        "non_medical_elevated_head_stack",
        "non_medical_warm_bath_stack",
        "non_medical_steam_inhalation_stack",
        "divider_2",
        "quick_actions_heading",
        "quick_action_doctor_button",
        "quick_action_faqs_button",
        "divider_3",
        "sources_heading",
        "source_aap_stack",
        "source_cdc_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Supporting Your 5-Year-Old Through a Common Cold",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "When a 5-year-old experiences a common cold with a runny nose and mild cough, the primary goal is to manage symptoms and provide comfort. Many over-the-counter (OTC) cold and cough medications are not recommended for children under 6 years old. Focus on supportive care and remedies proven safe for this age group."
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "section_h2_remedies": {
      "type": "Text",
      "props": {
        "text": "Safe Remedies and Comfort Measures",
        "variant": "h2"
      },
      "children": []
    },
    "subsection_h3_otc": {
      "type": "Text",
      "props": {
        "text": "Over-the-Counter Remedies",
        "variant": "h3"
      },
      "children": []
    },
    "otc_saline_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "otc_saline_title_stack",
        "otc_saline_desc"
      ]
    },
    "otc_saline_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "otc_saline_icon",
        "otc_saline_title"
      ]
    },
    "otc_saline_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000373_01_1_droplet-fill.svg"
      },
      "children": []
    },
    "otc_saline_title": {
      "type": "Text",
      "props": {
        "text": "Saline Nasal Drops or Spray:",
        "variant": "body"
      },
      "children": []
    },
    "otc_saline_desc": {
      "type": "Text",
      "props": {
        "text": "Helps thin mucus and clear nasal passages. Apply a few drops or sprays in each nostril, then gently encourage your child to blow their nose."
      },
      "children": []
    },
    "otc_honey_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "otc_honey_title_stack",
        "otc_honey_desc"
      ]
    },
    "otc_honey_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "otc_honey_icon",
        "otc_honey_title"
      ]
    },
    "otc_honey_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000373_01_2_cup-hot.svg"
      },
      "children": []
    },
    "otc_honey_title": {
      "type": "Text",
      "props": {
        "text": "Honey (for cough relief):",
        "variant": "body"
      },
      "children": []
    },
    "otc_honey_desc": {
      "type": "Text",
      "props": {
        "text": "A spoonful of honey can help soothe a cough. Give 1/2 to 1 teaspoon as needed, especially before bedtime. (Note: Only for children over 1 year old)."
      },
      "children": []
    },
    "otc_pain_relievers_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "otc_pain_relievers_title_stack",
        "otc_pain_relievers_desc"
      ]
    },
    "otc_pain_relievers_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "otc_pain_relievers_icon",
        "otc_pain_relievers_title"
      ]
    },
    "otc_pain_relievers_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000373_01_3_thermometer-half.svg"
      },
      "children": []
    },
    "otc_pain_relievers_title": {
      "type": "Text",
      "props": {
        "text": "Pain Relievers (if discomfort/fever develops):",
        "variant": "body"
      },
      "children": []
    },
    "otc_pain_relievers_desc": {
      "type": "Text",
      "props": {
        "text": "Acetaminophen (e.g., Tylenol) or ibuprofen (e.g., Motrin, Advil) can be used to alleviate discomfort or mild fever, if present. Always follow dosage instructions based on your child's weight and age."
      },
      "children": []
    },
    "subsection_h3_non_medical": {
      "type": "Text",
      "props": {
        "text": "Non-Medical Comfort Measures",
        "variant": "h3"
      },
      "children": []
    },
    "non_medical_hydration_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "non_medical_hydration_title_stack",
        "non_medical_hydration_desc"
      ]
    },
    "non_medical_hydration_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "non_medical_hydration_icon",
        "non_medical_hydration_title"
      ]
    },
    "non_medical_hydration_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000373_01_4_water.svg"
      },
      "children": []
    },
    "non_medical_hydration_title": {
      "type": "Text",
      "props": {
        "text": "Hydration:",
        "variant": "body"
      },
      "children": []
    },
    "non_medical_hydration_desc": {
      "type": "Text",
      "props": {
        "text": "Offer plenty of fluids like water, clear broths, diluted juice, or electrolyte solutions to prevent dehydration and help thin mucus."
      },
      "children": []
    },
    "non_medical_rest_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "non_medical_rest_title_stack",
        "non_medical_rest_desc"
      ]
    },
    "non_medical_rest_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "non_medical_rest_icon",
        "non_medical_rest_title"
      ]
    },
    "non_medical_rest_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000373_01_5_bed.svg"
      },
      "children": []
    },
    "non_medical_rest_title": {
      "type": "Text",
      "props": {
        "text": "Rest:",
        "variant": "body"
      },
      "children": []
    },
    "non_medical_rest_desc": {
      "type": "Text",
      "props": {
        "text": "Ensure your child gets plenty of rest. Sleep helps the body recover and fight off infection."
      },
      "children": []
    },
    "non_medical_humidifier_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "non_medical_humidifier_title_stack",
        "non_medical_humidifier_desc"
      ]
    },
    "non_medical_humidifier_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "non_medical_humidifier_icon",
        "non_medical_humidifier_title"
      ]
    },
    "non_medical_humidifier_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000373_01_6_cloud.svg"
      },
      "children": []
    },
    "non_medical_humidifier_title": {
      "type": "Text",
      "props": {
        "text": "Humidifier:",
        "variant": "body"
      },
      "children": []
    },
    "non_medical_humidifier_desc": {
      "type": "Text",
      "props": {
        "text": "Use a cool-mist humidifier in your child's room to help ease congestion and cough. Clean it regularly to prevent mold growth."
      },
      "children": []
    },
    "non_medical_elevated_head_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "non_medical_elevated_head_title_stack",
        "non_medical_elevated_head_desc"
      ]
    },
    "non_medical_elevated_head_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "non_medical_elevated_head_icon",
        "non_medical_elevated_head_title"
      ]
    },
    "non_medical_elevated_head_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000373_01_7_head-up.svg"
      },
      "children": []
    },
    "non_medical_elevated_head_title": {
      "type": "Text",
      "props": {
        "text": "Elevated Head:",
        "variant": "body"
      },
      "children": []
    },
    "non_medical_elevated_head_desc": {
      "type": "Text",
      "props": {
        "text": "For children over 2, elevating the head of the bed slightly (e.g., by placing books under the mattress) can help with post-nasal drip and cough. Do not use pillows for infants."
      },
      "children": []
    },
    "non_medical_warm_bath_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "non_medical_warm_bath_title_stack",
        "non_medical_warm_bath_desc"
      ]
    },
    "non_medical_warm_bath_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "non_medical_warm_bath_icon",
        "non_medical_warm_bath_title"
      ]
    },
    "non_medical_warm_bath_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000373_01_8_bath.svg"
      },
      "children": []
    },
    "non_medical_warm_bath_title": {
      "type": "Text",
      "props": {
        "text": "Warm Bath:",
        "variant": "body"
      },
      "children": []
    },
    "non_medical_warm_bath_desc": {
      "type": "Text",
      "props": {
        "text": "A warm bath can be soothing and help relax muscles, potentially easing discomfort from a cold."
      },
      "children": []
    },
    "non_medical_steam_inhalation_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "non_medical_steam_inhalation_title_stack",
        "non_medical_steam_inhalation_desc"
      ]
    },
    "non_medical_steam_inhalation_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "non_medical_steam_inhalation_icon",
        "non_medical_steam_inhalation_title"
      ]
    },
    "non_medical_steam_inhalation_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000373_01_9_steam.svg"
      },
      "children": []
    },
    "non_medical_steam_inhalation_title": {
      "type": "Text",
      "props": {
        "text": "Steam Inhalation:",
        "variant": "body"
      },
      "children": []
    },
    "non_medical_steam_inhalation_desc": {
      "type": "Text",
      "props": {
        "text": "Sitting with your child in a steamy bathroom (run a hot shower) for 10-15 minutes can help loosen mucus and relieve congestion. Supervise closely."
      },
      "children": []
    },
    "divider_2": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_action_doctor_button": {
      "type": "Button",
      "props": {
        "label": "When to Call a Doctor"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.healthychildren.org/English/ages-stages/preschool/Pages/When-to-Call-the-Doctor-for-a-Cold.aspx"
          }
        }
      },
      "children": []
    },
    "quick_action_faqs_button": {
      "type": "Button",
      "props": {
        "label": "Cold & Flu FAQs"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.cdc.gov/flu/season/faq-flu-season.htm"
          }
        }
      },
      "children": []
    },
    "divider_3": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "source_aap_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "source_aap_icon",
        "source_aap_text"
      ]
    },
    "source_aap_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000373_01_10_link.svg"
      },
      "children": []
    },
    "source_aap_text": {
      "type": "Text",
      "props": {
        "text": "American Academy of Pediatrics (AAP)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.healthychildren.org/English/ages-stages/preschool/Pages/Common-Colds.aspx"
          }
        }
      },
      "children": []
    },
    "source_cdc_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "source_cdc_icon",
        "source_cdc_text"
      ]
    },
    "source_cdc_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000373_01_11_link.svg"
      },
      "children": []
    },
    "source_cdc_text": {
      "type": "Text",
      "props": {
        "text": "Centers for Disease Control and Prevention (CDC)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.cdc.gov/features/rhinoviruses/index.html"
          }
        }
      },
      "children": []
    }
  }
}
